{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C34"],
      "claim": "Bumetanide, the closest structural analogue, had an absolute oral bioavailability of 90% in healthy subjects after a 1 mg dose, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "In 12 normal volunteers, bumetanide oral solution absolute bioavailability was 0.69, still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Bumetanide oral tablet absolute bioavailability was 0.86 ± 0.13 in normal subjects, independently supporting high oral bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a close pyrrolidine analogue of bumetanide. Bumetanide has consistently high absolute oral bioavailability in humans (approximately 69-95%), far above the 20% threshold. The conservative structural change from butylamino to pyrrolidinyl is unlikely to reduce F below 20%, so the prediction is high.",
  "evidence_gaps": [
    "No direct pharmacokinetic data exist for the exact pyrrolidine analogue.",
    "The effect of the pyrrolidine substitution on first-pass metabolism or transporter-mediated disposition is not experimentally characterized.",
    "All relevant evidence comes from one structural family, bumetanide analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

